code.java:
class Solution {
    public int specialArray(int[] nums){
        for(int x=0;x<=nums.length;x++){
            int count=0;
            for(int value:nums)if(value>=x)count++;
            if(count==x)return x;
        }
        return -1;
    }
}

code.kotlin:
class Solution {
    fun specialArray(nums:IntArray):Int{
        for(x in 0..nums.size)if(nums.count{
            it>=x
        }==x)return x;
        return -1
    }
}

code.cpp:
class Solution {
    public: int specialArray(vector<int>& nums){
        for(int x=0;x<=(int)nums.size();++x)if(count_if(nums.begin(),nums.end(),[&](int value){
            return value>=x;
        })==x)return x;
        return -1;
    }
};
